// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Send power command to AMT device
	// (POST /api/v1/amt/devices/{uuid}/power)
	AmtPowerAction(w http.ResponseWriter, r *http.Request, uuid openapi_types.UUID)
	// Query audit log (admin only)
	// (GET /api/v1/audit)
	ListAuditEvents(w http.ResponseWriter, r *http.Request, params ListAuditEventsParams)
	// Authenticate user
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Register a new user
	// (POST /api/v1/auth/register)
	Register(w http.ResponseWriter, r *http.Request)
	// Report a browser-side error for server-side log ingestion
	// (POST /api/v1/client-errors)
	ReportClientError(w http.ResponseWriter, r *http.Request)
	// List devices, optionally filtered by group
	// (GET /api/v1/devices)
	ListDevices(w http.ResponseWriter, r *http.Request, params ListDevicesParams)
	// Count devices currently in maintenance
	// (GET /api/v1/devices/maintenance-summary)
	GetDeviceMaintenanceSummary(w http.ResponseWriter, r *http.Request)
	// Delete device
	// (DELETE /api/v1/devices/{id})
	DeleteDevice(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Get device details
	// (GET /api/v1/devices/{id})
	GetDevice(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Update device fields
	// (PATCH /api/v1/devices/{id})
	UpdateDevice(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Rank anomalous metric dimensions for a device window
	// (POST /api/v1/devices/{id}/correlate)
	CorrelateDevice(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Get hardware info for a device
	// (GET /api/v1/devices/{id}/hardware)
	GetDeviceHardware(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// On-demand full-resolution local history for one dimension
	// (GET /api/v1/devices/{id}/history)
	GetDeviceHistory(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, params GetDeviceHistoryParams)
	// Discovered software and service inventory for a device
	// (GET /api/v1/devices/{id}/inventory)
	GetDeviceInventory(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Broker an on-demand raw-log pull from a device
	// (GET /api/v1/devices/{id}/logs)
	GetDeviceLogs(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, params GetDeviceLogsParams)
	// Enter or exit maintenance mode for a device
	// (POST /api/v1/devices/{id}/maintenance)
	SetDeviceMaintenance(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Downsampled numeric telemetry for a device window
	// (GET /api/v1/devices/{id}/metrics)
	GetDeviceMetrics(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, params GetDeviceMetricsParams)
	// Restart agent on device
	// (POST /api/v1/devices/{id}/restart)
	RestartDevice(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Enroll agent using token (public)
	// (POST /api/v1/enroll/{token})
	Enroll(w http.ResponseWriter, r *http.Request, token string)
	// List enrollment tokens (admin only)
	// (GET /api/v1/enrollment-tokens)
	ListEnrollmentTokens(w http.ResponseWriter, r *http.Request)
	// Create enrollment token (admin only)
	// (POST /api/v1/enrollment-tokens)
	CreateEnrollmentToken(w http.ResponseWriter, r *http.Request)
	// Delete enrollment token (admin only)
	// (DELETE /api/v1/enrollment-tokens/{id})
	DeleteEnrollmentToken(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List user's groups
	// (GET /api/v1/groups)
	ListGroups(w http.ResponseWriter, r *http.Request)
	// Create a device group
	// (POST /api/v1/groups)
	CreateGroup(w http.ResponseWriter, r *http.Request)
	// Delete group
	// (DELETE /api/v1/groups/{id})
	DeleteGroup(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Get group details
	// (GET /api/v1/groups/{id})
	GetGroup(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Health check
	// (GET /api/v1/health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// Purge all telemetry for an organization (admin only)
	// (POST /api/v1/orgs/{orgId}/purge)
	PurgeOrg(w http.ResponseWriter, r *http.Request, orgId openapi_types.UUID)
	// Get purge job status
	// (GET /api/v1/purge-jobs/{jobId})
	GetPurgeJob(w http.ResponseWriter, r *http.Request, jobId openapi_types.UUID)
	// Remove push subscription
	// (DELETE /api/v1/push/subscribe)
	UnsubscribePush(w http.ResponseWriter, r *http.Request)
	// Save browser push subscription
	// (POST /api/v1/push/subscribe)
	SubscribePush(w http.ResponseWriter, r *http.Request)
	// Get server VAPID public key
	// (GET /api/v1/push/vapid-key)
	GetVapidKey(w http.ResponseWriter, r *http.Request)
	// List all security groups (admin only)
	// (GET /api/v1/security-groups)
	ListSecurityGroups(w http.ResponseWriter, r *http.Request)
	// Create a security group (admin only)
	// (POST /api/v1/security-groups)
	CreateSecurityGroup(w http.ResponseWriter, r *http.Request)
	// Delete a security group (admin only)
	// (DELETE /api/v1/security-groups/{id})
	DeleteSecurityGroup(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Get security group with members (admin only)
	// (GET /api/v1/security-groups/{id})
	GetSecurityGroup(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Add user to security group (admin only)
	// (POST /api/v1/security-groups/{id}/members)
	AddSecurityGroupMember(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Remove user from security group (admin only)
	// (DELETE /api/v1/security-groups/{id}/members/{userId})
	RemoveSecurityGroupMember(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, userId openapi_types.UUID)
	// Get server CA certificate PEM
	// (GET /api/v1/server/ca)
	GetServerCA(w http.ResponseWriter, r *http.Request)
	// Get agent install script
	// (GET /api/v1/server/install.sh)
	GetInstallScript(w http.ResponseWriter, r *http.Request)
	// List active sessions for a device
	// (GET /api/v1/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request, params ListSessionsParams)
	// Create a relay session
	// (POST /api/v1/sessions)
	CreateSession(w http.ResponseWriter, r *http.Request)
	// Delete a relay session
	// (DELETE /api/v1/sessions/{token})
	DeleteSession(w http.ResponseWriter, r *http.Request, token string)
	// List all agent update manifests
	// (GET /api/v1/updates/manifests)
	ListUpdateManifests(w http.ResponseWriter, r *http.Request)
	// Publish a new agent binary version (admin only)
	// (POST /api/v1/updates/manifests)
	PublishUpdate(w http.ResponseWriter, r *http.Request)
	// Push update to connected agents (admin only)
	// (POST /api/v1/updates/push)
	PushUpdate(w http.ResponseWriter, r *http.Request)
	// Get the Ed25519 public signing key
	// (GET /api/v1/updates/signing-key)
	GetUpdateSigningKey(w http.ResponseWriter, r *http.Request)
	// Get per-device update status for a version (admin only)
	// (GET /api/v1/updates/status/{version})
	GetUpdateStatus(w http.ResponseWriter, r *http.Request, version string)
	// List all users (admin only)
	// (GET /api/v1/users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// Get current user
	// (GET /api/v1/users/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// Delete user (admin only)
	// (DELETE /api/v1/users/{id})
	DeleteUser(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Update user (admin only)
	// (PATCH /api/v1/users/{id})
	UpdateUser(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
}

